export function relevantIncidents(scenario){const ids=new Set(collect(scenario).map(n=>n.id));return incidents.filter(i=>i.affected.some(id=>ids.has(id)));}
export function collect(scenario) {
  const visited = new Set();
  function walk(id) { if(visited.has(id))return; visited.add(id); for(const e of scenario.edges)if(e[0]===id)walk(e[1]); }
  walk(scenario.root); return [...visited].map(id=>nodes[id]);
}
export function depth(scenario) {
  function walk(id,path=new Set()) { if(path.has(id))return 0; const next=new Set(path).add(id);const es=scenario.edges.filter(e=>e[0]===id&&e[3]!=='network');return 1+Math.max(0,...es.map(e=>walk(e[1],next))); }
  return walk(scenario.root);
}
export function riskFactors(scenario){return [...new Set(collect(scenario).flatMap(n=>n.risks.map(r=>r[0])))];}
export function riskLevel(scenario){const levels={low:0,medium:1,high:2};return collect(scenario).reduce((a,n)=>levels[n.level]>levels[a]?n.level:a,'low');}
export function lookup(query,chain){const q=query.trim().toLowerCase();return scenarios.find(s=>s.chain===chain&&s.address?.toLowerCase()===q)||scenarios.find(s=>s.chain===chain&&(s.id===q||s.symbol.toLowerCase()===q));}
export function validateAddress(s){return /^0x[0-9a-fA-F]{40}$/.test(s);}
export function relatedNodes(scenario,id){const set=new Set();function walk(n){if(set.has(n))return;set.add(n);scenario.edges.filter(e=>e[0]===n).forEach(e=>walk(e[1]));}walk(id);return set;}
